-- Jetty import from reconciled SQLite database
BEGIN;

CREATE TEMP TABLE jetty_import (
  site_date date, no_tiket int,
  gross_jetty_kg int, tare_jetty_kg int, netto_jetty_kg int,
  cp3_timestamp timestamptz
);


UPDATE trips SET
  gross_jetty_kg   = j.gross_jetty_kg,
  tare_jetty_kg    = j.tare_jetty_kg,
  netto_jetty_kg   = j.netto_jetty_kg,
  compare_gross_kg = j.gross_jetty_kg - COALESCE(trips.gross_site_kg, 0),
  deviasi_kg       = j.netto_jetty_kg - COALESCE(trips.netto_site_kg, 0),
  cp3_timestamp    = j.cp3_timestamp,
  status           = 'completed'
FROM jetty_import j
WHERE trips.date = j.site_date AND trips.no_tiket = j.no_tiket;

COMMIT;
